"use client";

import React, { useMemo, useState } from "react";
import { 
  ChevronLeft, ChevronRight, Plus, Trash2, Copy, 
  Check, Save, Wand2, Calendar, Lock, Palmtree, AlertTriangle 
} from "lucide-react";
import { Modal } from "@/components/ui/modal";

/* ---------------- 1. GOVERNANCE DATA ---------------- */
// In a real app, these would come from your API based on the user's region/ID
const HOLIDAYS = ["2026-01-26"]; // Republic Day
const APPROVED_LEAVES = ["2026-01-27", "2026-01-28"]; // User applied for these days

/* ---------------- TYPES & HELPERS ---------------- */
// ... (Previous Types remain the same) ...

const formatDate = (d: Date) => d.toISOString().split("T")[0];
const addDays = (d: Date, days: number) => {
    const nd = new Date(d);
    nd.setDate(nd.getDate() + days);
    return nd;
};
const startOfWeek = (date: Date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    d.setHours(0, 0, 0, 0);
    return d;
};

export default function GovernedTimesheet() {
    // Start week on Jan 26th to demonstrate the Holiday/Leave logic
    const [weekStart, setWeekStart] = useState(startOfWeek(new Date("2026-01-26")));
    const [timesheet, setTimesheet] = useState<any>({
        weekStart: formatDate(weekStart),
        status: "DRAFT",
        entries: {},
    });
    
    const [selectedDate, setSelectedDate] = useState<string | null>(null);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    /* ---------------- 2. SMART DAY GENERATION ---------------- */
    const days = useMemo(() => {
        return Array.from({ length: 7 }).map((_, i) => {
            const d = addDays(weekStart, i);
            const dateStr = formatDate(d);
            
            // Validation Flags
            const isHoliday = HOLIDAYS.includes(dateStr);
            const isLeave = APPROVED_LEAVES.includes(dateStr);
            const isBlocked = isHoliday || isLeave;

            return {
                label: d.toLocaleDateString("en-US", { weekday: "short" }),
                date: dateStr,
                dayNum: d.getDate(),
                isWeekend: i === 5 || i === 6,
                isHoliday,
                isLeave,
                isBlocked,
                entries: timesheet.entries[dateStr] || []
            };
        });
    }, [weekStart, timesheet.entries]);

    /* ---------------- 3. VALIDATED ACTIONS ---------------- */

    const addEntry = (date: string) => {
        const dayInfo = days.find(d => d.date === date);
        
        // STRICT VALIDATION
        if (dayInfo?.isHoliday) {
            setErrorMsg(`Cannot log hours on ${date}: It is a Public Holiday.`);
            return;
        }
        if (dayInfo?.isLeave) {
            setErrorMsg(`Cannot log hours on ${date}: You are on Approved Leave.`);
            return;
        }

        // Add entry logic...
        const newEntry = {
            id: crypto.randomUUID(),
            projectId: "p1",
            type: "BILLABLE",
            hours: 0,
            notes: ""
        };
        setTimesheet((prev: any) => ({
            ...prev,
            entries: { ...prev.entries, [date]: [...(prev.entries[date] || []), newEntry] }
        }));
    };

    const handleAutoFill = () => {
        const newEntries = { ...timesheet.entries };
        
        days.slice(0, 5).forEach(d => {
            // SMART FILL: Skip if Holiday, Leave, or already has entries
            if (d.isBlocked || (newEntries[d.date] && newEntries[d.date].length > 0)) return;

            newEntries[d.date] = [{
                id: crypto.randomUUID(),
                projectId: "p1", // Default Project
                type: "BILLABLE",
                hours: 8,
                notes: "Standard working day"
            }];
        });
        setTimesheet((prev: any) => ({ ...prev, entries: newEntries }));
    };

    return (
        <div className="mx-auto max-w-7xl px-4 py-8 space-y-6">
            
            {/* Header & Controls (Same as before) ... */}

            {/* ERROR TOAST */}
            {errorMsg && (
                <div className="bg-red-50 text-red-600 px-4 py-3 rounded-xl border border-red-100 flex items-center justify-between animate-shake">
                    <div className="flex items-center gap-2 font-bold text-sm">
                        <AlertTriangle size={16} /> {errorMsg}
                    </div>
                    <button onClick={() => setErrorMsg(null)} className="text-red-400 hover:text-red-700"><Trash2 size={14} /></button>
                </div>
            )}

            {/* MAIN GRID */}
            <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
                {days.map((d) => (
                    <div 
                        key={d.date} 
                        className={`
                            relative min-h-[200px] flex flex-col rounded-2xl border transition-all
                            ${d.isBlocked 
                                ? "bg-slate-50/50 dark:bg-white/[0.02] border-slate-100 dark:border-slate-800" // Locked Look
                                : "bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 hover:border-blue-300"
                            }
                        `}
                    >
                        {/* Header */}
                        <div className="p-4 flex justify-between items-center">
                            <div>
                                <div className="text-xs font-bold uppercase text-slate-400">{d.label}</div>
                                <div className={`text-xl font-bold ${d.isBlocked ? 'text-slate-400' : 'text-slate-900 dark:text-white'}`}>{d.dayNum}</div>
                            </div>
                            
                            {/* VISUAL INDICATORS */}
                            {d.isHoliday && (
                                <span className="bg-purple-100 text-purple-600 p-1.5 rounded-lg" title="Public Holiday">
                                    <Calendar size={14} />
                                </span>
                            )}
                            {d.isLeave && (
                                <span className="bg-amber-100 text-amber-600 p-1.5 rounded-lg" title="On Leave">
                                    <Palmtree size={14} />
                                </span>
                            )}
                        </div>

                        {/* Content Area */}
                        <div className="flex-1 p-2">
                            {d.isBlocked ? (
                                <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-2 select-none">
                                    {d.isHoliday ? <Lock size={20} /> : <Palmtree size={20} />}
                                    <span className="text-[10px] font-bold uppercase tracking-widest">
                                        {d.isHoliday ? "Holiday" : "Leave"}
                                    </span>
                                </div>
                            ) : (
                                /* Render Entries Loop ... */
                                <div className="space-y-2">
                                    {d.entries.map((e: any) => (
                                        <div key={e.id} className="bg-blue-50 text-blue-700 p-2 rounded text-xs font-bold">{e.hours}h • Billable</div>
                                    ))}
                                    
                                    {/* Add Button */}
                                    <button 
                                        onClick={() => addEntry(d.date)}
                                        className="w-full py-2 border border-dashed border-slate-200 text-slate-400 rounded hover:border-blue-400 hover:text-blue-500 transition-colors"
                                    >
                                        <Plus size={16} className="mx-auto" />
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
            
            {/* Action Bar */}
            <div className="flex justify-end gap-4">
                 <button onClick={handleAutoFill} className="flex items-center gap-2 text-sm font-bold text-slate-600 bg-white border border-slate-200 px-4 py-2 rounded-lg hover:bg-slate-50">
                    <Wand2 size={16} className="text-purple-500" /> Smart Auto-Fill
                 </button>
            </div>
        </div>
    );
}